// --- Helpers ---
function stripHtml(html) {
  return String(html || "")
    .replace(/<style[\s\S]*?<\/style>/gi, "")
    .replace(/<script[\s\S]*?<\/script>/gi, "")
    .replace(/<[^>]*>/g, "")
    .replace(/&nbsp;/g, " ")
    .trim();
}

// Remove things that shouldn't count toward language detection
function sanitizeForDetection(text) {
  return String(text || "")
    // strip markdown links [text](url)
    .replace(/\[[^\]]*]\([^)]+\)/g, " ")
    // strip raw URLs
    .replace(/\bhttps?:\/\/\S+/gi, " ")
    .replace(/\bwww\.\S+/gi, " ")
    // strip emails
    .replace(/\b\S+@\S+\.\S+\b/g, " ")
    // strip hex-y ids like 0xabc123..., tx hashes, codes
    .replace(/\b0x[a-f0-9]{6,}\b/gi, " ")
    .replace(/\b[a-f0-9]{16,}\b/gi, " ")
    // strip numbers
    .replace(/[0-9]+/g, " ")
    // strip common punctuation/symbols but keep apostrophes for can't/I'm
    .replace(/[!"\u201c\u201d#$%&()*+,\-./:;<=>?@[\\\]^_`{|}~]/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

// Very common English stopwords (small/fast)
const stop = new Set([
  "the","be","to","of","and","a","in","that","have","it","for","not","on","with",
  "you","do","at","this","but","by","from","we","say","or","an","will","my","all",
  "there","their","is","are","was","were","can","please","help","i","he","she","they"
]);

// Small-but-effective English vocab
const common = new Set([
  "the","be","to","of","and","a","in","that","it","for","not","on","with","as","you",
  "do","at","this","but","his","by","from","they","we","say","her","she","or","an",
  "will","my","one","all","would","there","their","is","are","was","were","been","being",
  "have","has","had","can","could","should","would","may","might","must","shall",
  "please","help","issue","error","login","account","reset","password","how","what",
  "why","where","when","which","who","whom","does","did","done","trying","unable"
]);

const item = items[0];

// --- Input text (what we will pass to Kapa) ---
const cleanDescription = stripHtml(
  item.json?.body?.description ??
  item.json?.description ??
  ""
);

// --- Detection text (numbers/links/symbols removed) ---
const detectText = sanitizeForDetection(cleanDescription);

// Tokens for detection: only letters + apostrophes (keeps can't/I'm)
const tokens = (detectText.toLowerCase().match(/[a-z]+(?:'[a-z]+)?/g) || []);

// --- Metrics (on sanitized text) ---
const asciiChars = (detectText.match(/[\x00-\x7F]/g) || []).length;
const asciiRatio = asciiChars / Math.max(1, detectText.length);

const stopHits   = tokens.filter(t => stop.has(t)).length;
const commonHits = tokens.filter(t => common.has(t)).length;

const stopRatio   = stopHits   / Math.max(1, tokens.length);
const commonRatio = commonHits / Math.max(1, tokens.length);

// --- Thresholds ---
const minTokens       = 4;
const minAscii        = 0.95;
const minStopRatio    = 0.08;
const minCommonRatio  = 0.25;

let isEnglish =
  tokens.length >= minTokens &&
  asciiRatio >= minAscii &&
  stopRatio >= minStopRatio &&
  commonRatio >= minCommonRatio;

// Short-query fallback: "can't login please help", etc.
if (!isEnglish && tokens.length > 0 && tokens.length < 10) {
  isEnglish = (commonHits >= 2 && stopHits >= 1 && asciiRatio >= minAscii);
}

// Extra safety: if we stripped almost everything but still have strong English cues, allow it.
if (!isEnglish && tokens.length >= 2) {
  const strongCues = ["please","help","issue","error","login","reset","password","account"];
  const hasCue = tokens.some(t => strongCues.includes(t));
  if (hasCue && asciiRatio >= minAscii) isEnglish = true;
}

return [{
  json: {
    ...item.json,
    cleanDescription,
    languageCheck: {
      isEnglish,
      asciiRatio,
      tokens: tokens.length,
      stopHits,
      stopRatio,
      commonHits,
      commonRatio
    }
  }
}];

// Parse tags coming from the webhook payload and merge with new ones

// 1) Read whatever Freshdesk sent. In your payload it's body.tags (often "" or "tag1, tag2")
const incoming = $json.body?.tags;

// 2) Convert to an array of strings (robust to CSV, space-separated, or JSON array)
let existing = [];
if (Array.isArray(incoming)) {
  existing = incoming;
} else if (typeof incoming === 'string') {
  const s = incoming.trim();
  if (!s) {
    existing = [];
  } else if (s.startsWith('[')) {
    try { existing = JSON.parse(s); } catch { existing = s.split(','); }
  } else if (s.includes(',')) {
    existing = s.split(',');
  } else {
    existing = s.split(/\s+/);
  }
} else {
  existing = [];
}

// 3) Your new tags to add (customize this array)
const toAdd = ['kapa_answered'];

// 4) Normalize, trim, and de-duplicate (case-insensitive)
const merged = [];
const seen = new Set();
for (const t of [...existing, ...toAdd]) {
  const raw = String(t ?? '').trim();
  if (!raw) continue;
  const key = raw.toLowerCase();
  if (!seen.has(key)) { seen.add(key); merged.push(raw); }
}

// 5) Output merged list for the next node
return [{ ...$json, merged_tags: merged }];

