={{
  (() => {
    const projectId = "YOUR_KAPA_PROJECT_ID";

    const raw =
      $json.thread_id ??
      $json.kapa_thread_id ??
      $json.threadId ??
      "";
    const threadId = String(raw).trim().replace(/^["']|["']$/g, "");

    const qaId = String($json.question_answer_id ?? $json.kapa_qa_id ?? "").trim();

    const url = threadId
      ? `https://app.kapa.ai/${projectId}/conversations/${encodeURIComponent(threadId)}`
      : "";

    const body = url
      ? `Kapa conversation link\nThread ID: ${threadId}\nQ/A ID: ${qaId || "—"}\nOpen in Kapa: ${url}`
      : `Kapa conversation link unavailable (no thread ID)\nQ/A ID: ${qaId || "—"}`;

    return JSON.stringify({ body, private: true });
  })()
}}
